import { BrowserRouter, Routes, Route } from "react-router-dom";
import Login from "./demofrontlogin";
import Main from "./mainHomePage";
import ProtectedRoute from "./protect/ProtectedRoute";
//import Editor from "./components/editor";
import { Navigate } from "react-router-dom";


function App() {
  return (
    <BrowserRouter>
      <Routes>

        {/* Login Page */}
        <Route path="/" element={<Login />} />

        {/* Home Page (Protected) */}
        <Route
          path="/mainHomePage"
          element={
            <ProtectedRoute>
              <Main />
            </ProtectedRoute>
          }
        />
        <Route
          path="/editor"
        element={
          localStorage.getItem("token") ? <Editor /> : <Navigate to="/login" />
  }
/> 

        {/* Any wrong URL → Login page */}
        <Route path="*" element={<Login />} />

      </Routes>
    </BrowserRouter>
  );
}

export default App;
